const $ = (selector, root = document) => root.querySelector(selector);
const $$ = (selector, root = document) => [...root.querySelectorAll(selector)];
const tierNames = { 1: 'Bronze', 2: 'Silver', 3: 'Gold', 4: 'Platinum' };
function storedJson(key){try{return JSON.parse(sessionStorage.getItem(key)||'null');}catch{return null;}}
const state = { session: null, invitationSession: null, member: null, prompts: [], marketplace: null, marketplaceCategory: 'ai-services-agents', selectedMarketplaceItem: null, onboarding: null, tourStep: -1, admin: null, platformAdmin: false, assessment: null, assessmentStep: 0, assessmentDraft: {}, workspace: { profile: null, outputs: [], generations: [], favorites: [] }, category: 'all', importPayload: null, currentOutput: null, currentPage: 'dashboard', previewRank: null, appMode: location.pathname.startsWith('/admin') || location.pathname.startsWith('/platform') ? 'admin' : 'member', impersonation: storedJson('d9-impersonation') };

function escapeHtml(value) { const node = document.createElement('div'); node.textContent = String(value ?? ''); return node.innerHTML; }
function toast(value, error = false) { const el = $('#toast'); el.textContent = value; el.className = `toast show${error ? ' error' : ''}`; clearTimeout(toast.timer); toast.timer = setTimeout(() => el.className = 'toast', 3500); }
function message(form, value, success = false) { const el = $('[data-message]', form); if (el) { el.textContent = value || ''; el.classList.toggle('success', success); } }
function setBusy(form, busy) { $$('button', form).forEach((button) => button.disabled = busy); form?.classList.toggle('is-busy', busy); }
async function api(path, options = {}) { const headers = { ...(options.body ? { 'Content-Type': 'application/json' } : {}), ...(state.session?.access_token ? { Authorization: `Bearer ${state.session.access_token}` } : {}), ...(state.impersonation?.id ? { 'X-Impersonation-Session': state.impersonation.id } : {}), ...(state.previewRank ? { 'X-Preview-Tier': tierNames[state.previewRank] } : {}), ...(options.headers || {}) }; const result = await fetch(`/api/${path}`, { ...options, headers }); const body = await result.json().catch(() => ({})); if (!result.ok) { const error = new Error(body.error || 'Something went wrong.'); error.status = result.status; throw error; } return body; }
function saveSession(session) { state.session = session; sessionStorage.setItem('d9-platform-session', JSON.stringify(session)); }
function signOut() { closeTour(); state.session = state.member = state.admin = state.assessment = state.onboarding = null; state.prompts=[]; state.workspace={profile:null,outputs:[],generations:[],favorites:[]}; state.previewRank=null; state.impersonation=null; sessionStorage.removeItem('d9-platform-session'); sessionStorage.removeItem('d9-impersonation'); $('#previewBanner').classList.add('hidden'); $('#appView').classList.add('hidden'); $('#verifyForm').classList.add('hidden'); $('#loginForm').classList.remove('hidden'); $('#authView').classList.remove('hidden'); $('#loginForm').reset(); history.replaceState({},'',state.appMode==='admin'?'/admin/login':'/login'); configureAuthScreen(); }
function showVerification() { $('#loginForm').classList.add('hidden'); $('#verifyForm').classList.remove('hidden'); $('#verifyForm [name=email]').value = state.session?.user?.email || ''; }
function showInvitationError(value){$('#loginForm').classList.add('hidden');$('#verifyForm').classList.add('hidden');const form=$('#invitationSetupForm');form.classList.remove('hidden');$$('label,.button.primary',form).forEach((item)=>item.classList.add('hidden'));message(form,value);}
function readInvitationCallback(){if(location.pathname!=='/auth/callback')return false;const values=new URLSearchParams(location.hash.replace(/^#/,'')),accessToken=values.get('access_token'),refreshToken=values.get('refresh_token'),authType=values.get('type'),error=values.get('error_description')||values.get('error');history.replaceState({},'',`${location.pathname}${location.search}`);$('#loginForm').classList.add('hidden');$('#verifyForm').classList.add('hidden');$('#invitationSetupForm').classList.remove('hidden');if(error||!['invite','recovery'].includes(authType)||!accessToken||!refreshToken){showInvitationError('This invitation link is invalid or has expired. Ask an administrator to resend it.');return true;}const next=new URLSearchParams(location.search).get('next')||'/login';state.appMode=next.startsWith('/admin')||next.startsWith('/platform')?'admin':'member';state.invitationSession={access_token:accessToken,refresh_token:refreshToken,expires_in:Number(values.get('expires_in'))||3600,token_type:values.get('token_type')||'bearer',auth_type:authType};return true;}

$('#loginForm').addEventListener('submit', async (event) => { event.preventDefault(); const form = event.currentTarget; message(form, ''); setBusy(form, true); try { saveSession(await api('auth-session', { method: 'POST', body: JSON.stringify(Object.fromEntries(new FormData(form))) })); await enterApp(); } catch (error) { message(form, error.message); } finally { setBusy(form, false); } });
$('#verifyForm').addEventListener('submit', async (event) => { event.preventDefault(); const form = event.currentTarget; message(form, ''); setBusy(form, true); try { await api('member-eligibility', { method: 'POST', body: JSON.stringify(Object.fromEntries(new FormData(form))) }); await enterApp(); } catch (error) { message(form, error.message); } finally { setBusy(form, false); } });
$('#invitationSetupForm').addEventListener('submit',async(event)=>{event.preventDefault();const form=event.currentTarget,password=form.elements.password.value;if(!state.invitationSession)return showInvitationError('This invitation link is invalid or has expired. Ask an administrator to resend it.');if(password!==form.elements.password_confirmation.value)return message(form,'The passwords do not match.');message(form,'');setBusy(form,true);try{state.session=state.invitationSession;const result=await api('auth-session',{method:'POST',body:JSON.stringify({action:'complete_invitation',password})});saveSession({...state.invitationSession,user:result.user});state.invitationSession=null;history.replaceState({},'',state.appMode==='admin'?'/admin/login':'/login');await enterApp();}catch(error){state.session=null;message(form,error.message);}finally{setBusy(form,false);}});
document.addEventListener('click',(event)=>{if(!event.target.closest('[data-invitation-signin]'))return;state.invitationSession=null;history.replaceState({},'',state.appMode==='admin'?'/admin/login':'/login');$('#invitationSetupForm').classList.add('hidden');$('#loginForm').classList.remove('hidden');configureAuthScreen();});

async function enterApp() {
  try {
    if (state.appMode === 'admin') {
      try {
        state.admin = await api('admin-console');
        const account=state.admin.admin.account;
        state.platformAdmin=state.admin.admin.roles?.includes('platform_admin')||state.admin.admin.roles?.includes('super_admin'); showApp(); toggleMemberNav(false); configureAdminView(); configurePlatformView();
        setIdentity(account, account.account_designation || 'D9Network Administrator');
        $('#workspaceEyebrow').textContent='D9Network administration';
        if(state.impersonation){$('#previewMessage').textContent=`Viewing as ${state.impersonation.target_name || 'selected account'} · ${state.impersonation.viewed_role.replaceAll('_',' ')}${state.impersonation.simulated_tier?` · ${state.impersonation.simulated_tier}`:''} · Read only`;$('#previewBanner').classList.remove('hidden');}
        renderAdmin();
        const requested=pageFromPath(), destination=requested.page==='import'&&state.admin.admin.permissions.data?'import':'admin', requestedTab=location.pathname==='/admin/login'?null:requested.tab, selectedTab=adminTabAllowed(requestedTab)?requestedTab:firstAdminTab();
        state.adminTab=selectedTab;
        go(destination,false); showAdminTab(selectedTab); if(destination==='admin'&&(!requestedTab||requestedTab!==selectedTab))history.replaceState({page:'admin'},'',adminTabPath(selectedTab)); return;
      } catch (adminError) {
        if (adminError.status !== 403) throw adminError;
        state.appMode='member'; history.replaceState({accessDenied:true},'', '/dashboard?access-denied=1'); toast('You do not have permission to access Administration.',true);
      }
    }
    let data;
    try { data = await api('prompts-list'); }
    catch (memberError) { if (memberError.status === 403) { showVerification(); return; } throw memberError; }
    state.platformAdmin=Boolean(data.platform_admin); if(state.platformAdmin&&!state.admin){try{state.admin=await api('admin-console');}catch{}} state.member = data.member; state.prompts = data.prompts || []; state.marketplace=marketplaceFallback(); try{state.marketplace=await api('marketplace-list');}catch{} showApp(); toggleMemberNav(true); configurePlatformView(); renderMember();
    try { state.workspace = await api('member-workspace'); } catch { state.workspace = { profile: null, outputs: [], generations: [], favorites: [] }; }
    try { state.assessment = await api('assessment'); } catch { state.assessment = null; }
    await loadOnboarding(); await syncOnboardingMilestones(); renderAllMemberViews(); go('dashboard',false); maybeShowWelcomeTour();
    const requested=pageFromPath(); if(requested.page!=='dashboard'||location.pathname==='/dashboard') { if(requested.tab)state.adminTab=requested.tab; go(requested.page,false); if(requested.tab)showAdminTab(requested.tab); }
  } catch (error) { if (error.status === 403) return showVerification(); if (error.status === 401) return signOut(); toast(error.message, true); }
}
function showApp() { $('#authView').classList.add('hidden'); $('#appView').classList.remove('hidden'); }
function toggleMemberNav(show) { $('#memberNavLabel').classList.toggle('hidden',!show); $$('[data-page="dashboard"],.nav-group:not(.admin-group)').forEach((item) => item.classList.toggle('hidden', !show)); $('#topTourButton').classList.toggle('hidden',!show); $('#adminNav').classList.toggle('hidden',!state.admin); }
function configureAdminView() { const permissions=state.admin?.admin?.permissions||{}; $('#adminNav').classList.remove('hidden'); $$('[data-admin-role]').forEach((item)=>item.classList.toggle('hidden',!permissions[item.dataset.adminRole])); const dashboard=$('#adminNav [data-admin-tab="dashboard"]'); if(dashboard)dashboard.classList.toggle('hidden',!permissions.dashboard); }
function configurePlatformView(){const control=$('#platformViewControl'),select=$('#platformView');control.classList.toggle('hidden',!state.platformAdmin);if(!state.platformAdmin)return;select.value=state.appMode==='admin'?'platform':(state.previewRank?tierNames[state.previewRank]:'member');if(state.appMode==='member'){$('#previewMessage').textContent=state.previewRank?`Previewing the ${tierNames[state.previewRank]} member experience. Your role and membership are unchanged.`:'Member View for platform testing. Your role and membership are unchanged.';$('#previewBanner').classList.remove('hidden');}}
function initials(profile){return [profile?.first_name,profile?.last_name].filter(Boolean).map((part)=>String(part).trim()[0]).join('').toUpperCase();}
function setIdentity(profile, designation) { const name=[profile?.first_name,profile?.last_name].filter(Boolean).join(' '); $('#memberName').textContent=name; $('#memberTier').textContent=designation||''; $('#tierBadge').textContent=designation||''; $('#avatar').textContent=initials(profile); }
const invalidFirstNames=new Set(['your','user','null','undefined']);
function validFirstName(value){const name=String(value??'').trim();return name&&!invalidFirstNames.has(name.toLowerCase())?name:'';}
function personalizedFirstName(profile={},user=state.session?.user||{}){const metadata=user.user_metadata||user.metadata||{};const fullName=String(profile.full_name||metadata.full_name||user.full_name||'').trim();return validFirstName(profile.first_name)||validFirstName(metadata.first_name)||validFirstName(fullName.split(/\s+/)[0]);}
function personalizedGreeting(profile={},prefix='Welcome Back'){const first=personalizedFirstName(profile);return first?`${prefix}, ${first}`:prefix;}
function renderMember() { const first=personalizedFirstName(state.member), tier=state.member.growth_kit_tier||'', identity={...state.member,first_name:first||null}; setIdentity(identity,tier?`${tier} member`:''); $('#dashboardWelcome').textContent=personalizedGreeting(identity); }
const onboardingEmpty={tour_started:false,tour_completed:false,tour_skipped:false,tour_started_at:null,tour_completed_at:null,tour_skipped_at:null,profile_completed_at:null,assessment_completed_at:null,recommendations_reviewed_at:null,first_tool_used_at:null,first_strategy_saved_at:null,checklist_acknowledged_at:null};
function onboardingStorageKey(){return`d9-onboarding-${state.session?.user?.id||state.session?.user?.email||'member'}`;}
function localOnboarding(){try{return{...onboardingEmpty,...JSON.parse(localStorage.getItem(onboardingStorageKey())||'{}')};}catch{return{...onboardingEmpty};}}
function saveLocalOnboarding(value){try{localStorage.setItem(onboardingStorageKey(),JSON.stringify(value));}catch{}}
function applyOnboardingAction(current,action,extra={}){const next={...onboardingEmpty,...current},now=new Date().toISOString();if(action==='start_tour')Object.assign(next,{tour_started:true,tour_skipped:false,tour_started_at:next.tour_started_at||now});if(action==='skip_tour')Object.assign(next,{tour_skipped:true,tour_skipped_at:now});if(action==='complete_tour')Object.assign(next,{tour_started:true,tour_completed:true,tour_skipped:false,tour_started_at:next.tour_started_at||now,tour_completed_at:next.tour_completed_at||now});if(action==='acknowledge_checklist')next.checklist_acknowledged_at=next.checklist_acknowledged_at||now;if(action==='review_recommendations')next.recommendations_reviewed_at=next.recommendations_reviewed_at||now;if(action==='sync_milestones'){const map={profile_complete:'profile_completed_at',assessment_complete:'assessment_completed_at',recommendations_reviewed:'recommendations_reviewed_at',first_tool_used:'first_tool_used_at',first_strategy_saved:'first_strategy_saved_at'};Object.entries(map).forEach(([flag,column])=>{if(extra[flag]&&!next[column])next[column]=now;});}return next;}
async function loadOnboarding(){try{const result=await api('onboarding-state');state.onboarding={...onboardingEmpty,...result.onboarding};saveLocalOnboarding(state.onboarding);}catch{state.onboarding=localOnboarding();}}
async function persistOnboarding(action,extra={}){const fallback=applyOnboardingAction(state.onboarding,action,extra);state.onboarding=fallback;saveLocalOnboarding(fallback);try{const result=await api('onboarding-state',{method:'POST',body:JSON.stringify({action,...extra})});state.onboarding={...onboardingEmpty,...result.onboarding};saveLocalOnboarding(state.onboarding);}catch{}renderGettingStarted();return state.onboarding;}
async function syncOnboardingMilestones(){if(!state.onboarding)return;const facts={profile_complete:profileComplete(),assessment_complete:Boolean(state.assessment?.latest),recommendations_reviewed:Boolean(state.onboarding.recommendations_reviewed_at),first_tool_used:Boolean(state.workspace.generations?.length),first_strategy_saved:Boolean(state.workspace.outputs?.length)};const fields={profile_complete:'profile_completed_at',assessment_complete:'assessment_completed_at',recommendations_reviewed:'recommendations_reviewed_at',first_tool_used:'first_tool_used_at',first_strategy_saved:'first_strategy_saved_at'};if(Object.entries(facts).some(([key,value])=>value&&!state.onboarding[fields[key]]))await persistOnboarding('sync_milestones',facts);}
function onboardingChecklist(){const o=state.onboarding||onboardingEmpty;return[
  {label:'Create Your Account',complete:true,page:'dashboard'},
  {label:'Complete Business Profile',complete:Boolean(o.profile_completed_at||profileComplete()),page:'profile',cta:'Complete Business Profile →'},
  {label:'Complete Business Growth Assessment',complete:Boolean(o.assessment_completed_at||state.assessment?.latest),page:'assessment',cta:'Take Business Growth Assessment →'},
  {label:'Review Recommended Tools',complete:Boolean(o.recommendations_reviewed_at),page:'recommended',cta:'Review Your Recommendations →'},
  {label:'Use Your First AI Business Tool',complete:Boolean(o.first_tool_used_at||state.workspace.generations?.length),page:'library',cta:'Explore Your AI Business Tools →'},
  {label:'Save Your First Strategy',complete:Boolean(o.first_strategy_saved_at||state.workspace.outputs?.length),page:'library',cta:'Explore Your AI Business Tools →'}
];}
function renderGettingStarted(){const host=$('.dashboard-progress-content');if(!host)return;let root=$('#gettingStartedCard');if(!root){host.insertAdjacentHTML('afterbegin','<section id="gettingStartedCard" class="getting-started-card" aria-labelledby="gettingStartedTitle"></section>');root=$('#gettingStartedCard');}const items=onboardingChecklist(),complete=items.filter((item)=>item.complete).length,done=complete===items.length,o=state.onboarding||onboardingEmpty;root.classList.toggle('hidden',done&&Boolean(o.checklist_acknowledged_at));if(done&&o.checklist_acknowledged_at)return;if(done){root.innerHTML='<div class="getting-started-complete"><span aria-hidden="true">✓</span><div><p class="eyebrow">Getting Started Complete</p><h3 id="gettingStartedTitle">You’re ready to keep growing.</h3><p>Your onboarding history is saved. You can restart the platform tour at any time from Account.</p></div><button class="button subtle" data-acknowledge-onboarding>Got It</button></div>';return;}const next=items.find((item)=>!item.complete),percent=Math.round(complete/items.length*100);root.innerHTML=`<div class="getting-started-head"><div><p class="eyebrow">Getting Started</p><h3 id="gettingStartedTitle">Build Your Personalized Growth Experience</h3></div><div class="getting-started-progress"><b>${complete} of ${items.length} Complete</b><span>${percent}%</span></div></div><div class="getting-started-track" role="progressbar" aria-label="Getting Started progress" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${percent}"><span style="width:${percent}%"></span></div><div class="getting-started-body"><ul>${items.map((item)=>`<li class="${item.complete?'complete':''}"><span aria-hidden="true">${item.complete?'✓':'○'}</span>${escapeHtml(item.label)}</li>`).join('')}</ul><button class="button primary" data-page="${next.page}">${escapeHtml(next.cta)}</button></div>`;}
