function clearTourHighlight(){$$('.tour-highlight').forEach((element)=>element.classList.remove('tour-highlight'));}
function closeTour(){clearTourHighlight();state.tourStep=-1;$('#tourOverlay')?.classList.add('hidden');}
async function startTour(){const welcome=$('#onboardingWelcomeDialog');if(welcome?.open)welcome.close();await persistOnboarding('start_tour');state.tourStep=0;go('dashboard');renderTourStep();}
async function skipTour(){const welcome=$('#onboardingWelcomeDialog');if(welcome?.open)welcome.close();await persistOnboarding('skip_tour');}
