function renderTourStep(){clearTourHighlight();const overlay=$('#tourOverlay'),panel=$('#tourPanel'),next=$('#tourNext'),back=$('#tourBack'),action=$('#tourAction'),context=$('#tourContext');overlay.classList.remove('hidden');if(state.tourStep>=tourSteps.length){void persistOnboarding('complete_tour');$('#tourProgressLabel').textContent='Tour Complete';$('#tourProgressBar').style.width='100%';$('#tourEyebrow').textContent='You’re Ready';$('#tourTitle').textContent="You're Ready to Get Started";$('#tourCopy').textContent='Start by completing your Business Profile. The more complete your information is, the more relevant your personalized recommendations can be.';context.textContent='';back.classList.add('hidden');action.classList.remove('hidden');action.textContent='Return to Dashboard';action.dataset.tourDestination='dashboard';next.textContent='Complete My Business Profile →';next.dataset.tourDestination='profile';panel.focus();return;}const step=tourSteps[state.tourStep],target=$(step.target);target?.closest('details')?.setAttribute('open','');target?.classList.add('tour-highlight');$('#tourProgressLabel').textContent=`Step ${state.tourStep+1} of ${tourSteps.length}`;$('#tourProgressBar').style.width=`${Math.round((state.tourStep+1)/tourSteps.length*100)}%`;$('#tourEyebrow').textContent='Platform Tour';$('#tourTitle').textContent=step.title;$('#tourCopy').textContent=step.copy;context.textContent=step.context?step.context():'';back.classList.toggle('hidden',state.tourStep===0);action.classList.toggle('hidden',!step.action);action.textContent=step.action||'';action.dataset.tourDestination=step.page||'';next.textContent='Next';delete next.dataset.tourDestination;panel.focus();}
function advanceTour(direction=1){state.tourStep=Math.max(0,state.tourStep+direction);renderTourStep();}
