function guidanceCard(kind,title,text,extra=''){return `<section class="guidance-card guidance-${kind}"><h3>${escapeHtml(title)}</h3>${text?`<p>${escapeHtml(text)}</p>`:''}${extra}</section>`;}
function BusinessGuidanceSidebar(key){const content=businessGuidanceContent[key];if(!content)return'';const tips=(content.tips||[]).map(([title,text],index)=>`<article class="guidance-tip"><span aria-hidden="true">${index+1}</span><div><h3>${escapeHtml(title)}</h3><p>${escapeHtml(text)}</p></div></article>`).join('');const checklist=content.checklist?guidanceCard('checklist',content.checklist.title,'',`<ul>${content.checklist.items.map((item)=>`<li>${escapeHtml(item)}</li>`).join('')}</ul>`):'';const education=content.education?guidanceCard('education',content.education.title,content.education.text):'';const insight=content.insight?guidanceCard('insight','Did You Know?',content.insight):'';const resource=content.resource?`<section class="guidance-card guidance-resource"><h3>Resource Spotlight</h3><h4>${escapeHtml(content.resource.title)}</h4><p>${escapeHtml(content.resource.text)}</p><span class="guidance-coming">${escapeHtml(content.resource.status||'Coming Soon')}</span></section>`:'';let next;if(key==='profile')next=profileComplete()?{title:'Take the Business Growth Assessment',text:'Identify your strongest areas, growth gaps, and recommended next actions.',page:'assessment',label:'Start Assessment'}:{title:'Complete Your Business Profile',text:'The more complete your profile is, the more relevant your recommendations, strategies, and future opportunities can become.',page:'profile',label:'Continue Profile'};else if(key==='assessment')next=state.assessment?.latest?{title:'Start With Your Top Priority',text:'Choose one recommended action or AI Business Tool and begin there.',page:'library',label:'Explore Recommended Tools'}:{title:'Complete the Assessment',text:'Answer each section candidly to identify strengths, priorities, and useful next actions.',page:'assessment',label:'Continue Assessment'};else if(key==='savedStrategies'){const latest=state.workspace.outputs?.[0];next=latest?{title:'Review Your Latest Strategy',text:'Revisit the recommendations and choose the next action you will complete.',output:latest.id,label:'Open Strategy'}:{title:'Create Your First Strategy',text:'Choose a guided AI Business Tool and save the recommendations you want to act on.',page:'library',label:'Explore AI Business Tools'};}const nextAction=next?`<section class="guidance-card guidance-next"><h3>Recommended Next Step</h3><h4>${escapeHtml(next.title)}</h4><p>${escapeHtml(next.text)}</p><button class="button subtle" ${next.output?`data-open-output="${escapeHtml(next.output)}"`:`data-page="${escapeHtml(next.page)}"`}>${escapeHtml(next.label)}</button></section>`:'';const encouragement=content.encouragement?guidanceCard('encouragement',content.encouragement.title,content.encouragement.text):'';return `<div class="guidance-sticky"><header class="guidance-header"><span aria-hidden="true">↗</span><h2>${escapeHtml(content.title)}</h2></header><div class="guidance-tips">${tips}</div>${insight}${checklist}${education}${resource}${nextAction}${encouragement}</div>`;}
function renderBusinessGuidance(){$$('.business-guidance[data-guidance]').forEach((sidebar)=>{sidebar.innerHTML=BusinessGuidanceSidebar(sidebar.dataset.guidance);});}

