const sponsoredBusinessSpotlightFields=['advertiser_name','headline','description','image_url','destination_url','cta_text','start_date','end_date','placement','active','impressions','clicks'];
const sponsoredBusinessSpotlights=[];
function activeSponsoredSpotlight(placement='my_business_guidance'){const now=Date.now();return sponsoredBusinessSpotlights.find((item)=>item.active&&item.placement===placement&&(!item.start_date||new Date(item.start_date).getTime()<=now)&&(!item.end_date||new Date(item.end_date).getTime()>=now));}
function safeExternalUrl(value){try{const url=new URL(value);return ['http:','https:'].includes(url.protocol)?url.href:'';}catch{return'';}}
function SponsoredBusinessSpotlight(item){if(!item)return'';const imageUrl=safeExternalUrl(item.image_url),destination=safeExternalUrl(item.destination_url),image=imageUrl?`<img src="${escapeHtml(imageUrl)}" alt="${escapeHtml(item.advertiser_name||'Sponsored business')} logo">`:'';const cta=destination?`<a class="button subtle" href="${escapeHtml(destination)}" target="_blank" rel="sponsored noopener">${escapeHtml(item.cta_text||'Learn More')} →</a>`:'';return `<section class="guidance-card sponsored-business"><span class="sponsored-label">Sponsored</span>${image}<h3>${escapeHtml(item.headline||item.advertiser_name)}</h3><p>${escapeHtml(item.description||'')}</p>${cta}</section>`;}
function guidancePreference(){try{return localStorage.getItem('d9-growth-guidance-collapsed')==='true';}catch{return false;}}
function compactBusinessGuidanceSidebar(key){const content=businessGuidanceContent[key];if(!content)return'';if(guidancePreference())return `<button class="guidance-rail" data-guidance-toggle aria-expanded="false" aria-label="Expand Growth Guidance"><span aria-hidden="true">💡</span><b>Growth Guidance</b></button>`;const tips=(content.tips||[]).slice(0,2).map(([title,text])=>`<article class="guidance-tip"><span aria-hidden="true">💡</span><div><h3>Quick Tip: ${escapeHtml(title)}</h3><p>${escapeHtml(text)}</p></div></article>`).join('');let next;if(key==='profile')next=profileComplete()?{title:'Take the Business Growth Assessment',text:'Identify your strongest areas, growth gaps, and recommended next actions.',page:'assessment',label:'Start Assessment'}:{title:'Complete Your Business Profile',text:'The more complete your profile is, the more relevant your recommendations, strategies, and future opportunities can become.',page:'profile',label:'Continue Profile'};else if(key==='assessment')next=state.assessment?.latest?{title:'Start With Your Top Priority',text:'Choose one recommended action or AI Business Tool and begin there.',page:'library',label:'Explore Recommended Tools'}:{title:'Complete the Assessment',text:'Answer each section candidly to identify strengths, priorities, and useful next actions.',page:'assessment',label:'Continue Assessment'};else if(key==='savedStrategies'){const latest=state.workspace.outputs?.[0];next=latest?{title:'Review Your Latest Strategy',text:'Revisit the recommendations and choose the next action you will complete.',output:latest.id,label:'Open Strategy'}:{title:'Create Your First Strategy',text:'Choose a guided AI Business Tool and save the recommendations you want to act on.',page:'library',label:'Explore AI Business Tools'};}const nextAction=next?`<section class="guidance-card guidance-next"><h3>Recommended Next Step</h3><h4>${escapeHtml(next.title)}</h4><p>${escapeHtml(next.text)}</p><button class="button subtle" ${next.output?`data-open-output="${escapeHtml(next.output)}"`:`data-page="${escapeHtml(next.page)}"`}>${escapeHtml(next.label)}</button></section>`:'';const sponsored=SponsoredBusinessSpotlight(activeSponsoredSpotlight());const fallback=!sponsored?(content.resource?`<section class="guidance-card guidance-resource"><h3>D9Network Resource</h3><h4>${escapeHtml(content.resource.title)}</h4><p>${escapeHtml(content.resource.text)}</p><span class="guidance-coming">${escapeHtml(content.resource.status||'Coming Soon')}</span></section>`:guidanceCard('insight','Growth Insight',content.insight||content.education?.text||'')):'';return `<div class="guidance-sticky"><header class="guidance-header"><span aria-hidden="true">💡</span><h2>Growth Guidance</h2><button class="icon-button" data-guidance-toggle aria-expanded="true" aria-label="Collapse Growth Guidance">‹</button></header><div class="guidance-tips">${tips}</div>${sponsored||fallback}${nextAction}</div>`;}
renderBusinessGuidance=function(){$$('.business-guidance[data-guidance]').forEach((sidebar)=>{const collapsed=guidancePreference();sidebar.classList.toggle('is-collapsed',collapsed);sidebar.closest('.my-business-layout')?.classList.toggle('guidance-collapsed',collapsed);sidebar.innerHTML=compactBusinessGuidanceSidebar(sidebar.dataset.guidance);});};
