function marketplaceFallback(){return{categories:marketplaceCategories,items:marketplaceItems};}
function marketplaceCategoryOf(item){return item.marketplace_categories||marketplaceCategories.find((category)=>category.slug===item.category_slug)||{name:item.category||'AI Services & Agents',slug:item.category_slug||'ai-services-agents'};}
function marketplaceCard(item,compact=false){const category=marketplaceCategoryOf(item);return `<article class="marketplace-card ${compact?'compact':''}"><div class="marketplace-card-icon" aria-hidden="true">${iconSvg(item.slug.includes('opportunity')?'opportunities-procurement':item.slug.includes('marketing')?'marketing-content':item.slug.includes('partnership')||item.slug.includes('referral')?'sales-relationships':'leadership-growth')}</div><div class="marketplace-card-top"><span class="premium-badge">Premium</span><span>${escapeHtml(category.name)}</span></div><h3>${escapeHtml(item.name)}</h3><p>${escapeHtml(item.description)}</p><button class="button marketplace-cta" data-marketplace-service="${escapeHtml(item.slug)}">${escapeHtml(item.cta_label||'Learn More →')}</button></article>`;}
function renderMarketplace(){const data=state.marketplace||marketplaceFallback(),categories=data.categories||marketplaceCategories,items=data.items||marketplaceItems;$('#marketplaceCategories').innerHTML=categories.map((category)=>`<button class="category-chip ${state.marketplaceCategory===category.slug?'active':''}" data-marketplace-category="${escapeHtml(category.slug)}">${escapeHtml(category.name)}</button>`).join('');const category=categories.find((item)=>item.slug===state.marketplaceCategory),filtered=items.filter((item)=>marketplaceCategoryOf(item).slug===state.marketplaceCategory&&item.active!==false);$('#marketplaceGrid').innerHTML=filtered.length?filtered.map((item)=>marketplaceCard(item)).join(''):`<div class="marketplace-coming"><span>Coming Soon</span><h2>${escapeHtml(category?.name||'Marketplace Services')}</h2><p>${escapeHtml(category?.description||'Additional Marketplace services are being prepared.')}</p></div>`;}
function openMarketplaceService(slug){const data=state.marketplace||marketplaceFallback(),item=(data.items||[]).find((entry)=>entry.slug===slug)||marketplaceItems.find((entry)=>entry.slug===slug);if(!item)return;state.selectedMarketplaceItem=item;const list=(title,values)=>`<section><h3>${title}</h3><ul>${(values||[]).map((value)=>`<li>${escapeHtml(value)}</li>`).join('')}</ul></section>`;$('#marketplaceDetail').innerHTML=`<article class="marketplace-detail"><header><span class="premium-badge">Premium</span><p class="eyebrow">${escapeHtml(marketplaceCategoryOf(item).name)}</p><h1>${escapeHtml(item.name)}</h1><p class="page-description">${escapeHtml(item.description)}</p></header><div class="marketplace-detail-grid"><section><h3>Who It Is For</h3><p>${escapeHtml(item.who_it_is_for)}</p></section><section><h3>How It Uses Business Profile Context</h3><p>${escapeHtml(item.profile_context)}</p></section>${list('What It Helps With',item.helps_with)}${list('Key Capabilities',item.key_capabilities)}${list('Expected Member Inputs',item.expected_inputs)}${list('Potential Outputs',item.potential_outputs)}</div><footer><div><span>Pricing Status</span><b>${escapeHtml(item.pricing_status||'Pricing Coming Soon')}</b></div><button class="button primary" disabled>Coming Soon</button></footer></article>`;go('marketplace-detail');}
function heroGraphic(type='growth'){return `<div class="hero-visual hero-${type}">${iconSvg(type==='assessment'?'strategy-operations':'leadership-growth')}<span class="visual-node node-one">AI</span><span class="visual-node node-two">↗</span><span class="visual-node node-three">◎</span></div>`;}
function progressRing(percent,label){const safe=Math.max(0,Math.min(100,Number(percent)||0));return `<div class="progress-ring" style="--progress:${safe}" role="img" aria-label="${safe}% ${escapeHtml(label)}"><div><b>${safe}%</b><span>${escapeHtml(label)}</span></div></div>`;}
function statusCard(title,status,description,percent,action,page){return `<div class="status-card-body">${progressRing(percent,'Complete')}<div><span class="status-label">${escapeHtml(status)}</span><h3>${escapeHtml(title)}</h3><p>${escapeHtml(description)}</p>${action?`<button class="text-button" data-page="${page}">${escapeHtml(action)} →</button>`:''}</div></div>`;}
function promptCard(prompt,compact=false) { const category = categoryOf(prompt), favorite = favoriteIds().has(prompt.id), locked=Number(prompt.minimum_tier_rank)>effectiveRank(); return `<article class="prompt-card ${compact?'compact-card ':''}${locked?'locked':''}"><div class="tool-card-header">${categoryThumbnail(prompt,compact)}<div class="tool-card-copy"><div class="prompt-top"><span class="category-tag">${escapeHtml(category.name)}</span>${locked?'<span class="lock-badge">Locked</span>':`<button class="favorite ${favorite ? 'active' : ''}" data-favorite="${prompt.id}" aria-label="${favorite ? 'Remove from' : 'Add to'} favorites">${favorite ? '★' : '☆'}</button>`}</div><h4>${escapeHtml(prompt.title)}</h4><p>${escapeHtml(prompt.description)}</p></div></div><div class="prompt-foot"><span>${prompt.estimated_minutes || 10} min · ${tierNames[prompt.minimum_tier_rank]}+</span><button class="button subtle" data-open-prompt="${prompt.id}">${locked?`Requires ${tierNames[prompt.minimum_tier_rank]}`:'Open Tool'}</button></div></article>`; }
function filteredPrompts() { const query = ($('#searchInput').value || '').trim().toLowerCase(); return state.prompts.filter((prompt) => (state.category === 'all' || categoryOf(prompt).slug === state.category) && (!query || `${prompt.title} ${prompt.description} ${(prompt.tags || []).join(' ')}`.toLowerCase().includes(query))); }
function renderLibrary() { const categories = [...new Map(state.prompts.map((prompt) => [categoryOf(prompt).slug, categoryOf(prompt)])).values()]; $('#categoryFilter').innerHTML = '<option value="all">All categories</option>' + categories.map((category) => `<option value="${escapeHtml(category.slug)}">${escapeHtml(category.name)}</option>`).join(''); $('#categoryFilter').value = state.category; $('#categoryCards').innerHTML = `<button class="category-chip ${state.category === 'all' ? 'active' : ''}" data-category="all">All Tools</button>` + categories.map((category) => `<button class="category-chip ${state.category === category.slug ? 'active' : ''}" data-category="${escapeHtml(category.slug)}">${escapeHtml(category.name)}</button>`).join(''); $('#toolNavCategories').innerHTML=categories.map((category)=>`<button data-page="library" data-category="${escapeHtml(category.slug)}">${escapeHtml(category.name)}</button>`).join(''); renderPromptResults(); }
function renderPromptResults() { const list = filteredPrompts(); $('#resultCount').textContent = `${list.length} result${list.length === 1 ? '' : 's'}`; $('#promptGrid').innerHTML = list.length ? list.map(promptCard).join('') : '<div class="empty"><h4>No matching tools</h4><p>Try a different goal, topic, or category.</p></div>'; }
function profileComplete() { const p = state.workspace.profile; return Boolean(p?.business_name && p?.industry && p?.business_description && p?.business_goals); }
function recommendedPrompts() { const p = state.workspace.profile || {}, favorites = favoriteIds(), priorities=assessmentResultData(state.assessment?.latest).priorities; const terms = `${p.industry || ''} ${p.business_stage || ''} ${p.business_goals || ''} ${(p.primary_business_challenges || []).join(' ')} ${p.geographic_market || ''} ${p.primary_markets_served || ''} ${p.markets_to_enter || ''} ${priorities.join(' ')}`.toLowerCase(); return [...state.prompts].sort((a,b) => { const score = (tool) => (favorites.has(tool.id) ? 5 : 0) + (tool.is_featured ? 3 : 0) + `${tool.title} ${tool.description} ${(tool.tags || []).join(' ')}`.toLowerCase().split(/\s+/).filter((word) => word.length > 4 && terms.includes(word)).length; return score(b) - score(a); }).slice(0,5); }
function recommendationReason(prompt){const assessment=(state.assessment?.latest?.recommendations||[]).find((item)=>(item.prompts?.id||item.prompt_id)===prompt.id);if(assessment?.reason)return assessment.reason;const profile=state.workspace.profile||{},category=categoryOf(prompt).name,challenges=profile.primary_business_challenges||[];if(challenges.length)return `Recommended to help address your ${challenges[0]} priority using your saved Business Profile context.`;if(profile.business_goals)return `Recommended because ${category} supports the business goals in your saved profile.`;if(profile.industry)return `Recommended for your ${profile.industry} business and current growth stage.`;return `Recommended as a practical next step in ${category}.`;}
function recommendedToolCard(prompt,reason,compact=false){const category=categoryOf(prompt);return `<article class="recommendation-card ${compact?'compact-recommendation':''}"><div class="recommendation-card-header">${categoryThumbnail(prompt,true)}<div><span class="category-tag">${escapeHtml(category.name)}</span><h4>${escapeHtml(prompt.title)}</h4><p>${escapeHtml(reason||recommendationReason(prompt))}</p></div></div><div class="included-note">Included With Your Membership</div><button class="button subtle" data-open-prompt="${prompt.id}">Use Tool →</button></article>`;}
function renderRecommended(){const root=$('#allRecommendations');if(!profileComplete()){root.innerHTML='<div class="empty"><h3>Complete your Business Profile</h3><p>Add your business context to receive useful, personalized Recommended Tools.</p><button class="button primary" data-page="profile">Complete Business Profile</button></div>';return;}const assessmentItems=state.assessment?.latest?.recommendations||[];root.innerHTML=assessmentItems.length?assessmentRecommendationCards(assessmentItems):recommendedPrompts().map((prompt)=>recommendedToolCard(prompt,recommendationReason(prompt))).join('');}
function savedMini(item) { return `<div class="saved-mini"><span class="document-icon" aria-hidden="true">▤</span><div><b>${escapeHtml(item.title)}</b><span>${new Date(item.created_at).toLocaleDateString()}</span></div><button class="button subtle" data-export-output="${item.id}">Export</button></div>`; }
