function renderAssessmentResults(latest){const r=assessmentResultData(latest),root=$('#assessmentResults');if(!latest){root.innerHTML='';return;}const list=(title,items,icon)=>`<article class="result-block status-card"><div class="result-icon">${iconSvg(icon)}</div><h4>${title}</h4>${items.length?`<ul>${items.map((item)=>`<li>${escapeHtml(item)}</li>`).join('')}</ul>`:'<p class="muted">No items identified in this area.</p>'}</article>`,premium=(state.marketplace?.items||marketplaceItems).find((item)=>item.slug==='opportunity-discovery-agent');root.innerHTML=`<div class="section-heading"><div><p class="eyebrow">Your Results</p><h2>Growth Priorities and Next Actions</h2><p class="page-description">Use these findings to choose a focused next action. A strategy or outcome is recorded only when you explicitly create and save one.</p></div></div><div class="assessment-results-grid">${list('Key Strengths',r.strengths,'leadership-growth')}${list('Areas for Improvement',r.improvements,'strategy-operations')}${list('Top 3 Growth Priorities',r.priorities,'opportunities-procurement')}${list('Suggested 30-Day Actions',r.actions30,'marketing-content')}${list('Suggested 90-Day Actions',r.actions90,'sales-relationships')}</div><div class="section-heading compact"><div><p class="eyebrow">Recommended Tools</p><h3>Included AI Business Tools for Your Priorities</h3></div><button class="text-button" data-page="library">View All My Tools →</button></div><div class="recommendation-grid">${assessmentRecommendationCards(r.recommendations)||'<div class="empty">No tool recommendations were needed.</div>'}</div>${premium?`<section class="assessment-premium-support"><div class="section-heading compact"><div><p class="eyebrow">Premium Support</p><h3>Optional Marketplace Service</h3></div></div>${marketplaceCard(premium,true)}</section>`:''}`;}
