function editorData(prompt = {}) { const form = $('#editorForm'); form.reset(); const fields = ['id','title','slug','description','user_prompt_template','output_format','marketplace_upgrade_message','estimated_minutes','status']; fields.forEach((key) => { if (form.elements[key]) form.elements[key].value = prompt[key] ?? (key === 'status' ? 'draft' : ''); }); form.elements.minimum_tier.value = tierNames[prompt.minimum_tier_rank] || 'Bronze'; form.elements.category_id.innerHTML = (state.admin.categories || []).map((c) => `<option value="${c.id}">${escapeHtml(c.name)}</option>`).join(''); if (prompt.category_id) form.elements.category_id.value = prompt.category_id; form.elements.questions.value = (prompt.form_schema || []).map((q) => `${q.key}|${q.label}`).join('\n'); form.elements.is_featured.checked = Boolean(prompt.is_featured); $('#deletePrompt').classList.toggle('hidden', !prompt.id); $('#editorTitle').textContent = prompt.id ? 'Edit Business Growth Tool' : 'New Business Growth Tool'; $('#editorDialog').showModal(); }
function ensurePromptConfigurationFields(){const form=$('#editorForm');if(form.elements.context_fields)return;const legacy=form.elements.user_prompt_template.closest('label');legacy.insertAdjacentHTML('beforebegin',`<label class="span-2">Context Fields <span class="hint">Comma-separated Business Profile field keys</span><textarea name="context_fields" rows="3"></textarea></label><label class="span-2">Task Template<textarea name="task_template" rows="5" required></textarea></label><label class="span-2">Required Output<textarea name="required_output" rows="7" required></textarea></label><label class="span-2">Guardrails<textarea name="guardrails" rows="4" required></textarea></label><label>Version <span class="hint">Increment when the prompt contract changes</span><input name="prompt_version" pattern="[0-9]+\\.[0-9]+" value="1.0" required></label>`);form.elements.user_prompt_template.required=false;legacy.childNodes[0].textContent='Compatibility Template (optional)';}
