const pagePaths={dashboard:'/dashboard',profile:'/business/profile',assessment:'/business/assessment',saved:'/strategies',recommended:'/recommendations',library:'/tools',workspace:'/tools/workspace',marketplace:'/marketplace','marketplace-detail':'/marketplace',opportunities:'/opportunities',settings:'/account/settings',admin:'/admin/dashboard',import:'/admin/imports'};
function pageFromPath(){const path=location.pathname;if(path==='/business/profile')return{page:'profile'};if(path==='/business/assessment')return{page:'assessment'};if(path==='/strategies')return{page:'saved'};if(path==='/recommendations')return{page:'recommended'};if(path.startsWith('/marketplace/')){const slug=path.split('/')[2];setTimeout(()=>openMarketplaceService(slug),0);return{page:'marketplace'};}if(path==='/marketplace')return{page:'marketplace'};if(path.startsWith('/tools/')){const part=path.split('/')[2];const category=['profile-branding','marketing-content','sales-relationships','strategy-operations','opportunities-procurement','leadership-growth'].includes(part);if(category){state.category=part;return{page:'library'};}const tool=state.prompts.find((item)=>item.slug===part);if(tool){setTimeout(()=>openTool(tool.id),0);return{page:'library'};}}if(path==='/tools')return{page:'library'};if(path==='/opportunities')return{page:'opportunities'};if(path==='/account/settings')return{page:'settings'};if(path.startsWith('/admin/')){const part=path.split('/')[2];const map={dashboard:'dashboard',members:'members',accounts:'accounts',invitations:'invitations',roles:'roles',testing:'testing',tools:'tools',marketplace:'marketplace',assessment:'assessment',imports:'imports',audit:'audit',reporting:'analytics'};return part==='imports'?{page:'import'}:{page:'admin',tab:map[part]||'dashboard'};}return{page:'dashboard'};}
function go(name,push=true){const permissions=state.admin?.admin?.permissions||{};if((name==='admin'&&!state.admin)||(name==='import'&&!permissions.data)){toast('You are not authorized to open that area.',true);name=state.member?'dashboard':'admin';}state.currentPage=name;$$('.page').forEach((page)=>page.classList.toggle('active',page.id===`page-${name}`));$$('[data-page]').forEach((item)=>item.classList.toggle('active',item.dataset.page===name));const titles={dashboard:'Dashboard',recommended:'Recommended Tools',library:'Included AI Business Tools',saved:'Saved Strategies',profile:'Business Profile',assessment:'Business Growth Assessment',marketplace:'Business Growth Marketplace','marketplace-detail':'Marketplace Service',opportunities:'Opportunity Center',workspace:'Strategy Workspace',admin:'Administration',import:'Member Synchronization',settings:'Settings'};$('#pageTitle').textContent=titles[name]||'Business Growth Platform';$('.sidebar').classList.remove('open');if(name==='recommended'&&state.onboarding&&!state.onboarding.recommendations_reviewed_at)void persistOnboarding('review_recommendations');if(push&&pagePaths[name]){const target=name==='library'&&state.category!=='all'?`/tools/${state.category}`:name==='marketplace-detail'&&state.selectedMarketplaceItem?`/marketplace/${state.selectedMarketplaceItem.slug}`:pagePaths[name];if(location.pathname!==target)history.pushState({page:name},'',target);}window.scrollTo(0,0);}

document.addEventListener('click',async(event)=>{const button=event.target.closest('button');if(!button)return;if(button.dataset.startTour!==undefined){event.preventDefault();event.stopImmediatePropagation();await startTour();return;}if(button.dataset.skipTour!==undefined){event.preventDefault();event.stopImmediatePropagation();await skipTour();return;}if(button.dataset.closeTour!==undefined){event.preventDefault();event.stopImmediatePropagation();closeTour();return;}if(button.dataset.tourBack!==undefined){event.preventDefault();event.stopImmediatePropagation();advanceTour(-1);return;}if(button.dataset.tourNext!==undefined){event.preventDefault();event.stopImmediatePropagation();if(button.dataset.tourDestination){const destination=button.dataset.tourDestination;closeTour();go(destination);}else advanceTour(1);return;}if(button.dataset.tourDestination){event.preventDefault();event.stopImmediatePropagation();const destination=button.dataset.tourDestination;closeTour();go(destination);return;}if(button.dataset.acknowledgeOnboarding!==undefined){event.preventDefault();event.stopImmediatePropagation();await persistOnboarding('acknowledge_checklist');}},true);
