document.addEventListener('click', async (event) => { const t=event.target.closest('button'); if (!t) return; if (t.dataset.page) return go(t.dataset.page); if (t.matches('[data-signout]')) return signOut(); if (t.dataset.openPrompt) return openTool(t.dataset.openPrompt); if (t.dataset.category) { state.category=t.dataset.category; renderLibrary(); return; } if (t.classList.contains('feedback-trigger')) return $('#feedbackDialog').showModal(); if (t.dataset.favorite) { const favorite=!favoriteIds().has(t.dataset.favorite); try { await api('member-workspace',{method:'POST',body:JSON.stringify({action:'set_favorite',prompt_id:t.dataset.favorite,favorite})}); await reloadWorkspace(); toast(favorite?'Tool added to favorites.':'Tool removed from favorites.'); } catch(e){toast(e.message,true);} return; } if (t.id==='clearBuilder') { $('#builderForm').reset(); $('#promptOutput').textContent='Your recommendations will appear here.'; $('#saveOutput').disabled=true; state.currentOutput=null; return; } if (t.id==='copyPrompt' && state.currentOutput) { await navigator.clipboard.writeText(state.currentOutput.output_text); toast('Strategy copied.'); return; } if (t.id==='saveOutput' && state.currentOutput) { try { await api('member-workspace',{method:'POST',body:JSON.stringify({action:'save_output',...state.currentOutput})}); await reloadWorkspace(); toast('Strategy saved.'); } catch(e){toast(e.message,true);} return; } const outputId=t.dataset.copyOutput||t.dataset.exportOutput||t.dataset.duplicateOutput||t.dataset.deleteOutput; if (outputId) { const item=(state.workspace.outputs||[]).find((x)=>x.id===outputId); if (t.dataset.copyOutput) { await navigator.clipboard.writeText(item.output_text); toast('Strategy copied.'); } if (t.dataset.exportOutput) { const blob=new Blob([`${item.title}\n${'='.repeat(item.title.length)}\n\n${item.output_text}`],{type:'text/plain'}),url=URL.createObjectURL(blob),link=document.createElement('a'); link.href=url; link.download=`${item.title.toLowerCase().replace(/[^a-z0-9]+/g,'-')}.txt`; link.click(); URL.revokeObjectURL(url); } if (t.dataset.duplicateOutput) { await api('member-workspace',{method:'POST',body:JSON.stringify({action:'duplicate_output',id:outputId})}); await reloadWorkspace(); toast('Strategy duplicated.'); } if (t.dataset.deleteOutput && confirm('Delete this saved strategy?')) { await api('member-workspace',{method:'POST',body:JSON.stringify({action:'delete_output',id:outputId})}); await reloadWorkspace(); toast('Saved strategy deleted.'); } return; } if (t.id==='newPrompt') return editorData(); if (t.dataset.editPrompt) return editorData(state.admin.prompts.find((p)=>p.id===t.dataset.editPrompt)); if (t.id==='newRole') return $('#roleDialog').showModal(); if (t.dataset.editCategory) return categoryEditor(state.admin.categories.find((c)=>c.id===t.dataset.editCategory)); if (t.id==='newCategory') return categoryEditor(); if (t.dataset.memberAccess) { await api('admin-console',{method:'POST',body:JSON.stringify({action:'set_member_access',id:t.dataset.memberAccess,enabled:t.dataset.enabled==='true'})}); await reloadAdmin(); toast('Member access updated.'); } if (t.dataset.removeRole && confirm('Remove this administrative role?')) { await api('admin-console',{method:'POST',body:JSON.stringify({action:'remove_role',email:t.dataset.email,role:t.dataset.role})}); await reloadAdmin(); } if (t.id==='commitImport') { t.disabled=true; try { const result=await api('admin-member-import',{method:'POST',body:JSON.stringify({...state.importPayload,preview:false})}); toast(`${result.totals.accepted} member records synchronized.`); state.importPayload=null; $('#importForm').reset(); $('#fileName').textContent='No file selected'; await reloadAdmin(); } catch(e){toast(e.message,true);t.disabled=false;} } });

