$('#profileForm').addEventListener('input',(event)=>{
  const field=event.target;
  if(field.name==='industry')validateProfileChoice(field,'industryOptions','Industry');
  if(field.name==='geographic_market')validateProfileChoice(field,'geographicMarketOptions','Geographic Market',true);
  if(['industry','business_stage','geographic_market'].includes(field.name))syncProfileConditionalFields(true);
  if(field.id==='challengeSearch'){const query=field.value.trim().toLowerCase();$$('#challengeOptions label').forEach((label)=>label.classList.toggle('hidden',!label.textContent.toLowerCase().includes(query)));}
});
$('#profileForm').addEventListener('change',(event)=>{
  const field=event.target;
  if(field.name==='business_certifications'){
    const exclusive=['None','Not Sure'];
    const fields=[...event.currentTarget.querySelectorAll('[name="business_certifications"]')];
    if(field.checked&&exclusive.includes(field.value))fields.forEach((item)=>{if(item!==field)item.checked=false;});
    else if(field.checked)fields.forEach((item)=>{if(exclusive.includes(item.value))item.checked=false;});
    syncProfileConditionalFields(true);
  }
  if(field.name==='primary_business_challenges')syncProfileConditionalFields(true);
});
