$('#assessmentForm').addEventListener('submit',async(e)=>{e.preventDefault();const form=e.currentTarget,stats=assessmentStats();if(stats.answered!==stats.total){message(form,'Complete every assessment section before submitting.');return;}setBusy(form,true);message(form,'');try{const answers={...state.assessmentDraft},data=await api('assessment',{method:'POST',body:JSON.stringify({action:'complete',answers})});state.assessment.latest={response:{completed_at:data.completed_at,answers},result:data.result,recommendations:data.result.recommendations};await persistOnboarding('sync_milestones',{assessment_complete:true});renderAssessment();renderDashboard();renderGettingStarted();renderBusinessGuidance();toast(data.preview?'Assessment saved to your administrator test workspace.':'Business Growth Assessment completed.');$('#assessmentResults').scrollIntoView({behavior:'smooth'});}catch(err){message(form,err.message);}finally{setBusy(form,false);}});
$('#feedbackForm').addEventListener('submit',async(e)=>{e.preventDefault();const form=e.currentTarget;setBusy(form,true);try{await api('member-workspace',{method:'POST',body:JSON.stringify({action:'submit_feedback',page:state.currentPage,...Object.fromEntries(new FormData(form))})});form.reset();$('#feedbackDialog').close();toast('Thank you. Your feedback was received.');}catch(err){message(form,err.message);}finally{setBusy(form,false);}});
$('#editorForm').addEventListener('submit',async(e)=>{e.preventDefault();const form=e.currentTarget,data=Object.fromEntries(new FormData(form));data.form_schema=String(data.questions||'').split(/\r?\n/).filter(Boolean).map((line,i)=>{const [key,...label]=line.split('|');return{key:label.length?key.trim():`answer${i+1}`,label:(label.join('|')||key).trim(),type:'textarea'};});data.is_featured=form.elements.is_featured.checked;try{await api('admin-console',{method:'POST',body:JSON.stringify({action:'save_prompt',prompt:data})});$('#editorDialog').close();await reloadAdmin();toast('Business Growth Tool saved.');}catch(err){message(form,err.message);}});
$('#roleForm').addEventListener('submit',async(e)=>{if(e.submitter?.value==='cancel')return;e.preventDefault();const form=e.currentTarget;if(form.dataset.submitting==='true')return;const data=Object.fromEntries(new FormData(form));data.permissions=String(data.permissions||'').split(',').map((item)=>item.trim()).filter(Boolean);form.dataset.submitting='true';message(form,'');setBusy(form,true);try{await api('admin-console',{method:'POST',body:JSON.stringify({action:'invite_account',...data})});$('#roleDialog').close();form.reset();await reloadAdmin();toast('Secure invitation sent.');}catch(err){message(form,err.message);}finally{delete form.dataset.submitting;setBusy(form,false);}});
$('#categoryForm').addEventListener('submit',async(e)=>{e.preventDefault();const form=e.currentTarget;try{await api('admin-console',{method:'POST',body:JSON.stringify({action:'save_category',category:Object.fromEntries(new FormData(form))})});$('#categoryDialog').close();await reloadAdmin();}catch(err){message(form,err.message);}});
$('#strategyForm').addEventListener('submit',async(e)=>{e.preventDefault();const form=e.currentTarget,data=Object.fromEntries(new FormData(form));data.is_favorite=form.elements.is_favorite.checked;setBusy(form,true);try{await api('member-workspace',{method:'POST',body:JSON.stringify({action:'update_strategy',...data})});$('#strategyDialog').close();await reloadWorkspace();toast('Saved Strategy updated.');}catch(err){message(form,err.message);}finally{setBusy(form,false);}});
$('#feedbackList').addEventListener('change',async(e)=>{if(!e.target.dataset.feedbackStatus)return;await api('admin-console',{method:'POST',body:JSON.stringify({action:'set_feedback_status',id:e.target.dataset.feedbackStatus,status:e.target.value})});toast('Feedback status updated.');});
$('#memberFile').addEventListener('change',(e)=>$('#fileName').textContent=e.target.files[0]?.name||'No file selected');
document.addEventListener('change',async(e)=>{const field=e.target,id=field.dataset.accountStatus||field.dataset.accountMembership||field.dataset.accountTier;if(!id)return;const payload={action:'set_account',id};if(field.dataset.accountStatus)payload.account_status=field.value;if(field.dataset.accountMembership)payload.membership_status=field.value;if(field.dataset.accountTier)payload.simulated_tier=field.value;field.disabled=true;try{await api('admin-console',{method:'POST',body:JSON.stringify(payload)});await reloadAdmin();toast('Account updated.');}catch(error){toast(error.message,true);field.disabled=false;}});
$('#importForm').addEventListener('submit',async(e)=>{e.preventDefault();const form=e.currentTarget,file=$('#memberFile').files[0];if(!file)return;setBusy(form,true);try{state.importPayload={filename:file.name,mime_type:file.type,file_base64:await fileToBase64(file)};const result=await api('admin-member-import',{method:'POST',body:JSON.stringify({...state.importPayload,preview:true})});const x=result.totals;$('#importPreview').innerHTML=`<h3>Synchronization Summary</h3><div class="summary-grid"><div><b>${x.accepted}</b><span>Accepted</span></div><div><b>${x.ignored}</b><span>Ignored</span></div><div><b>${x.rejected}</b><span>Rejected</span></div><div><b>${x.duplicates}</b><span>Duplicates</span></div></div>${x.ignored?'<p class="warning">Bronze II (Claim) and Ambassador records were ignored.</p>':''}<button id="commitImport" class="button primary">Commit ${x.accepted} member records</button>`;}catch(err){toast(err.message,true);}finally{setBusy(form,false);}});
document.addEventListener('click',(e)=>{const t=e.target.closest('button');if(!t)return;if(t.dataset.category){state.category=t.dataset.category;setTimeout(renderLibrary,0);}if(t.id==='inviteUser')$('#roleDialog').showModal();if(t.dataset.adminTab){state.adminTab=t.dataset.adminTab;setTimeout(()=>{showAdminTab(t.dataset.adminTab);const paths={dashboard:'/admin/dashboard',accounts:'/admin/accounts',invitations:'/admin/invitations',members:'/admin/members',roles:'/admin/roles',testing:'/admin/testing',tools:'/admin/tools',assessment:'/admin/assessment',audit:'/admin/audit',analytics:'/admin/reporting'};if(paths[t.dataset.adminTab])history.replaceState({page:'admin'},'',paths[t.dataset.adminTab]);},0);}},{capture:true});
document.addEventListener('click',async(e)=>{const t=e.target.closest('button');if(!t)return;if(t.dataset.openOutput){const item=(state.workspace.outputs||[]).find((x)=>x.id===t.dataset.openOutput);if(!item)return;const form=$('#strategyForm');form.elements.id.value=item.id;form.elements.title.value=item.title;form.elements.strategy_text.value=item.strategy_text;form.elements.is_favorite.checked=Boolean(item.is_favorite);$('#strategyDialog').showModal();}if(t.dataset.roleActive){await api('admin-console',{method:'POST',body:JSON.stringify({action:'set_role_active',id:t.dataset.roleActive,active:t.dataset.active==='true'})});await reloadAdmin();toast('Administrator access updated.');}if(t.dataset.resendInvitation){t.disabled=true;try{await api('admin-console',{method:'POST',body:JSON.stringify({action:'resend_invitation',id:t.dataset.resendInvitation})});await reloadAdmin();toast('Secure invitation sent again.');}catch(error){toast(error.message,true);if(t.isConnected)t.disabled=false;}}if(t.dataset.deleteInvitation){if(!window.confirm('Remove this failed invitation record?'))return;t.disabled=true;try{await api('admin-console',{method:'POST',body:JSON.stringify({action:'delete_invitation',id:t.dataset.deleteInvitation})});await reloadAdmin();toast('Failed invitation removed.');}catch(error){toast(error.message,true);if(t.isConnected)t.disabled=false;}}if(t.dataset.scrollAssessment)$('#assessmentSections').scrollIntoView({behavior:'smooth'});if(t.id==='helpButton')toast('Contact your D9Network administrator for account and access support.');if(t.dataset.opportunity)setTimeout(()=>document.getElementById(`opportunity-${t.dataset.opportunity}`)?.scrollIntoView({behavior:'smooth'}),0);});
document.addEventListener('click',(e)=>{$$('.nav-group[open]').forEach((menu)=>{if(!menu.contains(e.target))menu.removeAttribute('open');});});
document.addEventListener('keydown',(e)=>{if(e.key==='Escape')$$('.nav-group[open]').forEach((menu)=>menu.removeAttribute('open'));});
window.addEventListener('popstate',()=>{const target=pageFromPath();if(target.tab)state.adminTab=target.tab;go(target.page,false);if(target.tab)showAdminTab(target.tab);});
$('#platformView').addEventListener('change',async(e)=>{const value=e.target.value;if(value==='platform'){state.previewRank=null;state.appMode='admin';history.replaceState({view:'platform'},'', '/platform');}else{state.appMode='member';state.previewRank=value==='member'?null:Number(Object.entries(tierNames).find(([,name])=>name===value)?.[0]||4);history.replaceState({view:value},'',value==='member'?'/dashboard':`/dashboard?preview=${value.toLowerCase()}`);}await enterApp();});
$('#exitPreview').addEventListener('click',async()=>{if(state.platformAdmin&&!state.impersonation){state.previewRank=null;state.appMode='admin';$('#previewBanner').classList.add('hidden');history.replaceState({view:'platform'},'', '/platform');await enterApp();return;}if(!state.impersonation)return;try{const id=state.impersonation.id;await api('admin-console',{method:'POST',body:JSON.stringify({action:'end_impersonation',id})});state.impersonation=null;sessionStorage.removeItem('d9-impersonation');$('#previewBanner').classList.add('hidden');toast('View-as-user session ended.');}catch(error){toast(error.message,true);}});
$('#assessmentAdmin').addEventListener('change',async(e)=>{const field=e.target;if(field.dataset.questionOrder){await api('admin-console',{method:'POST',body:JSON.stringify({action:'save_assessment_question',question:{id:field.dataset.questionOrder,display_order:Number(field.value)}})});toast('Question order updated.');}if(field.dataset.sectionOrder){await api('admin-console',{method:'POST',body:JSON.stringify({action:'save_assessment_section',section:{id:field.dataset.sectionOrder,display_order:Number(field.value)}})});toast('Section order updated.');}});
$('#assessmentAdmin').addEventListener('click',async(e)=>{const button=e.target.closest('button');if(!button)return;if(button.dataset.questionActive)await api('admin-console',{method:'POST',body:JSON.stringify({action:'save_assessment_question',question:{id:button.dataset.questionActive,is_active:button.dataset.active==='true'}})});else if(button.dataset.sectionActive)await api('admin-console',{method:'POST',body:JSON.stringify({action:'save_assessment_section',section:{id:button.dataset.sectionActive,is_active:button.dataset.active==='true'}})});else if(button.dataset.mappingActive)await api('admin-console',{method:'POST',body:JSON.stringify({action:'save_assessment_mapping',mapping:{id:button.dataset.mappingActive,is_active:button.dataset.active==='true'}})});else if(button.dataset.addQuestion){const text=window.prompt('Enter the new assessment question.');if(!text)return;await api('admin-console',{method:'POST',body:JSON.stringify({action:'save_assessment_question',question:{section_id:button.dataset.addQuestion,question_text:text,answer_type:'yes_partial_no_na',display_order:100,is_active:true}})});}else if(button.dataset.addMapping){const select=$(`[data-mapping-tool="${button.dataset.addMapping}"]`);if(!select.value)return toast('Select a Business Growth Tool first.',true);await api('admin-console',{method:'POST',body:JSON.stringify({action:'save_assessment_mapping',mapping:{section_id:button.dataset.addMapping,prompt_id:select.value,priority:100,is_active:true}})});}else if(button.dataset.addSection){const title=window.prompt('Enter the new assessment section title.');if(!title)return;const version=state.admin.assessment.versions.find((item)=>item.is_active)||state.admin.assessment.versions[0];await api('admin-console',{method:'POST',body:JSON.stringify({action:'save_assessment_section',section:{version_id:version.id,title,slug:title.toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,''),display_order:999,is_active:true}})});}else return;await reloadAdmin();toast('Assessment configuration updated.');});
document.addEventListener('submit',async(e)=>{if(e.target.id!=='impersonationForm')return;e.preventDefault();const form=e.target,data=Object.fromEntries(new FormData(form));setBusy(form,true);try{const result=await api('admin-console',{method:'POST',body:JSON.stringify({action:'start_impersonation',...data})});state.impersonation=result.session;sessionStorage.setItem('d9-impersonation',JSON.stringify(result.session));$('#previewMessage').textContent=`Viewing as ${result.session.target_name || 'selected account'} · ${result.session.viewed_role.replaceAll('_',' ')}${result.session.simulated_tier?` · ${result.session.simulated_tier}`:''} · Read only`;$('#previewBanner').classList.remove('hidden');toast('Audited view-as-user session started.');}catch(error){message(form,error.message);}finally{setBusy(form,false);}});
function fileToBase64(file){return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result).split(',')[1]);reader.onerror=reject;reader.readAsDataURL(file);});}

document.addEventListener('click',(event)=>{const button=event.target.closest('button');if(!button)return;if(button.dataset.guidanceToggle!==undefined){event.preventDefault();try{localStorage.setItem('d9-growth-guidance-collapsed',String(!guidancePreference()));}catch{}renderBusinessGuidance();}if(button.dataset.dismissProfileNext!==undefined)$('#profileSaveNextStep').classList.add('hidden');});
document.addEventListener('click',(event)=>{const button=event.target.closest('button');if(button?.id!=='clearBuilder'||$('#saveOutput'))return;event.preventDefault();event.stopImmediatePropagation();$('#builderForm')?.reset();const output=$('#promptOutput');if(output)output.textContent='Your personalized prompt will appear here.';const copy=$('#copyBuiltPrompt'),used=$('#markToolUsed');if(copy)copy.disabled=true;if(used)used.disabled=true;state.currentOutput=null;},true);
document.addEventListener('click',(event)=>{const button=event.target.closest('button');if(!button)return;if(button.dataset.adminTab){event.preventDefault();event.stopImmediatePropagation();state.adminTab=button.dataset.adminTab;go('admin');showAdminTab(state.adminTab);history.replaceState({page:'admin'},'',adminTabPath(state.adminTab));return;}if(button.dataset.marketplaceService){event.preventDefault();event.stopImmediatePropagation();openMarketplaceService(button.dataset.marketplaceService);return;}if(button.dataset.marketplaceCategory){event.preventDefault();event.stopImmediatePropagation();state.marketplaceCategory=button.dataset.marketplaceCategory;renderMarketplace();go('marketplace');return;}if(button.dataset.category){event.preventDefault();event.stopImmediatePropagation();state.category=button.dataset.category;renderLibrary();go('library');}},true);

function configureAuthScreen(){const admin=state.appMode==='admin';$('#authEyebrow').textContent=admin?'Administrative access':'Member access';$('#authTitle').textContent=admin?'Sign in to Administration':'Welcome to your growth platform';$('#authDescription').textContent=admin?'Authorized D9Network administrators and staff can sign in here.':'Sign in with the email connected to your D9Network membership.';$('#verifyForm').classList.toggle('hidden',admin||$('#verifyForm').classList.contains('hidden'));}
configureAuthScreen();
if(!readInvitationCallback())try { const saved=JSON.parse(sessionStorage.getItem('d9-platform-session')||'null'); if(saved?.access_token){state.session=saved;enterApp();} } catch { sessionStorage.removeItem('d9-platform-session'); }
